//! The jj oracle corpus (`PLAN.md` §B5.2), generated by `script/gen-jj-oracle`.
//!
//! These tests check the corpus itself, then compare jj-mode alignment against it. Expected
//! values in the seed tests come from hand calculation with jj's rules (PLAN.md §B2).

#![expect(clippy::panic, reason = "test helpers outside `#[test]` panic on a failed check")]

use std::collections::{BTreeMap, HashSet};
use std::ops::Range;

use merge_core::document::{Labels, MergeDocument, MergeOptions, Output};
use merge_core::merge3::{
    HunkLevel, Inputs, Kind, Refine, Region, SameChange, Semantics, align, word_merge,
};
use merge_core::text::Text;
use serde::Deserialize;

const CORPUS: &str = include_str!("../../../fixtures/oracle/jj-corpus.jsonl");

/// Every case of the git corpus: its 45 seeds, 1900 mutations and 10 history cases.
const GIT_CASES: usize = 1955;
/// The hand seeds of `gen_jj_oracle.rs`.
const JJ_SEEDS: usize = 19;
const MODES: [&str; 4] = ["accept-line", "accept-word", "keep-line", "keep-word"];
/// jj's anchoring limit (`jj-core` `diff.rs`); the seeds sit on either side of it.
const MAX_OCCURRENCES: usize = 100;

#[derive(Debug, Deserialize)]
struct Case {
    id: String,
    sides: Vec<String>,
    bases: Vec<String>,
    merges: BTreeMap<String, Outcome>,
}

#[derive(Debug, Deserialize, PartialEq, Eq)]
struct Outcome {
    conflicts: usize,
    hunks: Vec<Hunk>,
}

#[derive(Debug, Deserialize, PartialEq, Eq, Clone)]
#[serde(rename_all = "snake_case")]
enum Hunk {
    Resolved(String),
    Conflict { sides: Vec<String>, bases: Vec<String> },
}

impl Case {
    fn merge(&self, mode: &str) -> &Outcome {
        &self.merges[mode]
    }
}

impl Outcome {
    fn conflict_hunks(&self) -> impl Iterator<Item = &Hunk> {
        self.hunks.iter().filter(|h| matches!(h, Hunk::Conflict { .. }))
    }
}

fn corpus() -> Vec<Case> {
    CORPUS.lines().map(|line| serde_json::from_str(line).expect("corpus line parses")).collect()
}

fn seed(id: &str) -> Case {
    corpus().into_iter().find(|c| c.id == id).unwrap_or_else(|| panic!("seed {id} exists"))
}

fn resolved(text: &str) -> Outcome {
    Outcome { conflicts: 0, hunks: vec![Hunk::Resolved(text.to_owned())] }
}

fn conflict(sides: &[&str], bases: &[&str]) -> Hunk {
    Hunk::Conflict {
        sides: sides.iter().map(|&s| s.to_owned()).collect(),
        bases: bases.iter().map(|&s| s.to_owned()).collect(),
    }
}

#[test]
fn corpus_holds_every_source_with_unique_ids_and_modes() {
    let cases = corpus();
    let count = |prefix: &str| cases.iter().filter(|c| c.id.starts_with(prefix)).count();
    assert_eq!((count("git-"), count("jj-")), (GIT_CASES, JJ_SEEDS));
    assert_eq!(cases.len(), GIT_CASES + JJ_SEEDS);
    let ids: HashSet<&str> = cases.iter().map(|c| c.id.as_str()).collect();
    assert_eq!(ids.len(), cases.len(), "ids are unique");
    for case in &cases {
        assert_eq!(
            case.merges.keys().map(String::as_str).collect::<Vec<_>>(),
            MODES,
            "{}",
            case.id
        );
        assert_eq!(case.sides.len(), case.bases.len() + 1, "{}", case.id);
    }
}

#[test]
fn hunks_alternate_and_conflicts_hold_every_input() {
    for case in corpus() {
        for (mode, merge) in &case.merges {
            let at = format!("{} {mode}", case.id);
            assert_eq!(merge.conflicts, merge.conflict_hunks().count(), "{at}");
            if merge.conflicts == 0 {
                assert_eq!(merge.hunks.len(), 1, "{at}: a clean merge is one text");
            }
            for pair in merge.hunks.windows(2) {
                assert_ne!(
                    matches!(pair[0], Hunk::Resolved(_)),
                    matches!(pair[1], Hunk::Resolved(_)),
                    "{at}: adjacent hunks of one kind"
                );
            }
            for hunk in &merge.hunks {
                match hunk {
                    Hunk::Resolved(text) => {
                        assert!(merge.conflicts == 0 || !text.is_empty(), "{at}: empty text");
                    }
                    Hunk::Conflict { sides, bases } => {
                        assert_eq!(
                            (sides.len(), bases.len()),
                            (case.sides.len(), case.bases.len()),
                            "{at}"
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn a_side_equal_to_base_gives_the_other_side_cleanly() {
    let mut checked = 0;
    for case in corpus().iter().filter(|c| c.sides.len() == 2) {
        let [left, right] = [&case.sides[0], &case.sides[1]];
        let base = &case.bases[0];
        let expected = if left == base {
            right
        } else if right == base {
            left
        } else {
            continue;
        };
        checked += 1;
        for mode in MODES {
            assert_eq!(case.merge(mode), &resolved(expected), "{} {mode}", case.id);
        }
    }
    assert!(checked > 0, "the corpus has cases with an unchanged side");
}

#[test]
fn identical_sides_resolve_only_when_the_same_change_is_accepted() {
    let mut checked = 0;
    for case in corpus()
        .iter()
        .filter(|c| c.sides.len() == 2 && c.sides[0] == c.sides[1] && c.sides[0] != c.bases[0])
    {
        checked += 1;
        let side = &case.sides[0];
        for mode in ["accept-line", "accept-word"] {
            assert_eq!(case.merge(mode), &resolved(side), "{} {mode}", case.id);
        }
        for mode in ["keep-line", "keep-word"] {
            let merge = case.merge(mode);
            assert!(merge.conflicts >= 1, "{} {mode}", case.id);
            for hunk in merge.conflict_hunks() {
                let Hunk::Conflict { sides, bases } = hunk else {
                    panic!("conflict_hunks yields conflicts");
                };
                assert_eq!(sides[0], sides[1], "{} {mode}: sides differ", case.id);
                assert_ne!(sides[0], bases[0], "{} {mode}: no change", case.id);
            }
        }
    }
    assert!(checked > 0, "the corpus has cases with identical changed sides");
}

#[test]
fn word_level_keeps_a_subset_of_the_line_level_conflicts() {
    for case in corpus() {
        for same_change in ["accept", "keep"] {
            let line = case.merge(&format!("{same_change}-line"));
            let word = case.merge(&format!("{same_change}-word"));
            let mut line_conflicts = line.conflict_hunks();
            for hunk in word.conflict_hunks() {
                assert!(
                    line_conflicts.any(|h| h == hunk),
                    "{} {same_change}: a word conflict that is not a line conflict",
                    case.id
                );
            }
        }
    }
}

#[test]
fn the_same_change_resolves_unless_kept() {
    let case = seed("jj-same-change");
    for mode in ["accept-line", "accept-word"] {
        assert_eq!(case.merge(mode), &resolved("a\nX\nc\n"), "{mode}");
    }
    let kept = Outcome {
        conflicts: 1,
        hunks: vec![
            Hunk::Resolved("a\n".to_owned()),
            conflict(&["X\n", "X\n"], &["b\n"]),
            Hunk::Resolved("c\n".to_owned()),
        ],
    };
    for mode in ["keep-line", "keep-word"] {
        assert_eq!(case.merge(mode), &kept, "{mode}");
    }
}

#[test]
fn a_line_conflict_of_separate_words_resolves_word_by_word() {
    let case = seed("jj-word-resolvable");
    let line = Outcome {
        conflicts: 1,
        hunks: vec![conflict(&["let y = 1;\n", "let x = 2;\n"], &["let x = 1;\n"])],
    };
    assert_eq!(case.merge("accept-line"), &line);
    assert_eq!(case.merge("accept-word"), &resolved("let y = 2;\n"));
}

#[test]
fn a_partly_resolvable_line_conflict_stays_whole() {
    let case = seed("jj-word-partial");
    let whole = Outcome {
        conflicts: 1,
        hunks: vec![conflict(&["let y = 1;\n", "let z = 2;\n"], &["let x = 1;\n"])],
    };
    for mode in MODES {
        assert_eq!(case.merge(mode), &whole, "{mode}");
    }
}

#[test]
fn a_same_word_change_beside_another_resolves_unless_kept() {
    let case = seed("jj-word-same-word");
    assert_eq!(case.merge("accept-word"), &resolved("y = 2;\n"));
    let whole =
        Outcome { conflicts: 1, hunks: vec![conflict(&["y = 2;\n", "x = 2;\n"], &["x = 1;\n"])] };
    for mode in ["accept-line", "keep-line", "keep-word"] {
        assert_eq!(case.merge(mode), &whole, "{mode}");
    }
}

#[test]
fn a_line_conflict_over_two_lines_word_merges_whole() {
    let case = seed("jj-word-two-lines");
    assert_eq!(case.merge("accept-word"), &resolved("A b\nc D\n"));
    assert_eq!(case.merge("accept-line").conflicts, 1);
}

#[test]
fn word_merging_keeps_each_sides_spacing() {
    let case = seed("jj-word-spaces");
    assert_eq!(case.merge("accept-word"), &resolved("g(a,  B)\n"));
}

#[test]
fn multi_byte_characters_belong_to_their_word() {
    let case = seed("jj-word-utf8");
    assert_eq!(case.merge("accept-word"), &resolved("naïf y\n"));
}

#[test]
fn lines_up_to_the_occurrence_limit_anchor() {
    let case = seed("jj-repeated-anchor-limit");
    let before =
        "z\n".to_owned() + &"x\n".repeat(MAX_OCCURRENCES) + &"y\n".repeat(MAX_OCCURRENCES - 1);
    let expected = Outcome {
        conflicts: 1,
        hunks: vec![Hunk::Resolved(before), conflict(&["y\nz\n", "Y\n"], &["y\n"])],
    };
    for mode in ["accept-line", "keep-line"] {
        assert_eq!(case.merge(mode), &expected, "{mode}");
    }
}

#[test]
fn lines_over_the_occurrence_limit_make_one_conflict() {
    let case = seed("jj-repeated-over-limit");
    let expected = Outcome {
        conflicts: 1,
        hunks: vec![Hunk::Conflict { sides: case.sides.clone(), bases: case.bases.clone() }],
    };
    for mode in ["accept-line", "keep-line"] {
        assert_eq!(case.merge(mode), &expected, "{mode}");
    }
}

#[test]
fn n_way_merges_cancel_each_base_against_an_equal_side() {
    let abc = "a\nb\nc\n";
    for id in ["jj-nway-resolves", "jj-nway-four-sides"] {
        for mode in MODES {
            assert_eq!(seed(id).merge(mode), &resolved("a\nX\nc\n"), "{id} {mode}");
        }
    }
    let two_changes = Outcome {
        conflicts: 1,
        hunks: vec![
            Hunk::Resolved("a\n".to_owned()),
            conflict(&["X\n", "Y\n", "b\n"], &["b\n", "b\n"]),
            Hunk::Resolved("c\n".to_owned()),
        ],
    };
    for mode in MODES {
        assert_eq!(seed("jj-nway-conflict").merge(mode), &two_changes, "{mode}");
    }
    let same = seed("jj-nway-same-change");
    assert_eq!(same.bases, [abc, abc]);
    assert_eq!(same.merge("accept-line"), &resolved("a\nX\nc\n"));
    assert_eq!(
        same.merge("keep-line"),
        &Outcome {
            conflicts: 1,
            hunks: vec![
                Hunk::Resolved("a\n".to_owned()),
                conflict(&["X\n", "X\n", "X\n"], &["b\n", "b\n"]),
                Hunk::Resolved("c\n".to_owned()),
            ],
        }
    );
}

#[test]
fn every_changed_side_making_the_same_change_resolves_with_more_sides() {
    let case = seed("jj-nway-same-change-cancelled");
    assert_eq!(case.merge("accept-line"), &resolved("a\nX\nc\n"));
    assert_eq!(
        case.merge("keep-line"),
        &Outcome {
            conflicts: 1,
            hunks: vec![
                Hunk::Resolved("a\n".to_owned()),
                conflict(&["X\n", "X\n", "Y\n"], &["Y\n", "b\n"]),
                Hunk::Resolved("c\n".to_owned()),
            ],
        }
    );
}

// jj mode against the corpus (PLAN.md §B5.3)

fn decode(s: &str) -> Text {
    Text::decode(s.as_bytes()).expect("corpus text decodes")
}

fn inputs(case: &Case) -> Inputs {
    let texts = |all: &[String]| all.iter().map(|t| decode(t)).collect();
    Inputs::new(texts(&case.sides), texts(&case.bases)).expect("the corpus holds valid shapes")
}

fn options(same_change: SameChange, hunk_level: HunkLevel, refine: bool) -> MergeOptions {
    MergeOptions {
        semantics: Semantics::Jj,
        same_change,
        hunk_level,
        refine: if refine { Refine::Ends } else { Refine::Off },
        ..MergeOptions::default()
    }
}

/// The corpus modes and the options each stands for.
const JJ_MODES: [(&str, SameChange, HunkLevel); 4] = [
    ("accept-line", SameChange::Accept, HunkLevel::Line),
    ("accept-word", SameChange::Accept, HunkLevel::Word),
    ("keep-line", SameChange::Keep, HunkLevel::Line),
    ("keep-word", SameChange::Keep, HunkLevel::Word),
];

fn span(text: &Text, range: &Range<usize>) -> String {
    text.span(range.clone()).to_owned()
}

/// The text a region resolves to on its own; none for a conflict.
fn auto_text(inputs: &Inputs, region: &Region, same_change: SameChange) -> Option<String> {
    match region.kind {
        Kind::Unchanged => Some(span(&inputs.bases()[0], &region.bases[0])),
        Kind::OneSide(i) => Some(span(&inputs.sides()[i], &region.sides[i])),
        Kind::AllSame => Some(span(&inputs.sides()[0], &region.sides[0])),
        Kind::WordMerged => {
            Some(word_merge(inputs, region, same_change).expect("a word-merged region merges"))
        }
        Kind::Conflict => None,
    }
}

/// jj's hunks from triad's regions: runs of resolved regions join into one text, and each
/// conflict holds every input's lines.
fn hunks(inputs: &Inputs, regions: &[Region], same_change: SameChange) -> Outcome {
    let mut hunks = Vec::new();
    let mut text = String::new();
    for region in regions {
        if let Some(resolved) = auto_text(inputs, region, same_change) {
            text.push_str(&resolved);
            continue;
        }
        if !text.is_empty() {
            hunks.push(Hunk::Resolved(std::mem::take(&mut text)));
        }
        let each = |texts: &[Text], ranges: &[Range<usize>]| {
            texts.iter().zip(ranges).map(|(t, r)| span(t, r)).collect()
        };
        hunks.push(Hunk::Conflict {
            sides: each(inputs.sides(), &region.sides),
            bases: each(inputs.bases(), &region.bases),
        });
    }
    if !text.is_empty() || hunks.is_empty() {
        hunks.push(Hunk::Resolved(text));
    }
    let conflicts = regions.iter().filter(|r| r.kind == Kind::Conflict).count();
    Outcome { conflicts, hunks }
}

#[test]
fn jj_mode_matches_every_case_hunk_for_hunk() {
    let failures: Vec<String> = corpus()
        .iter()
        .flat_map(|case| {
            let inputs = inputs(case);
            JJ_MODES.into_iter().filter_map(move |(mode, same_change, level)| {
                let regions = align(&inputs, options(same_change, level, false).alignment());
                (&hunks(&inputs, &regions, same_change) != case.merge(mode))
                    .then(|| format!("{} {mode}", case.id))
            })
        })
        .collect();
    assert_eq!(failures, Vec::<String>::new());
}

#[test]
fn refined_jj_mode_keeps_jjs_conflict_count_and_clean_output() {
    let failures: Vec<String> = corpus()
        .iter()
        .flat_map(|case| {
            JJ_MODES.into_iter().filter_map(move |(mode, same_change, level)| {
                let labels = Labels::none();
                let options = options(same_change, level, true);
                let doc = MergeDocument::new(inputs(case), options, labels).expect("no labels");
                let jj = case.merge(mode);
                let conflicts = doc.regions().iter().filter(|r| r.kind == Kind::Conflict).count();
                let clean = match jj.hunks.as_slice() {
                    [Hunk::Resolved(text)] if jj.conflicts == 0 => {
                        doc.output() == Output::Resolved(text.clone())
                    }
                    _ => !doc.output().is_resolved(),
                };
                (conflicts != jj.conflicts || !clean).then(|| format!("{} {mode}", case.id))
            })
        })
        .collect();
    assert_eq!(failures, Vec::<String>::new());
}

#[test]
#[expect(clippy::single_range_in_vec_init, reason = "a three-way merge has one base range")]
fn word_mode_merges_the_resolvable_seed_into_one_word_merged_region() {
    let case = seed("jj-word-resolvable");
    let inputs = inputs(&case);
    for refine in [false, true] {
        let regions =
            align(&inputs, options(SameChange::Accept, HunkLevel::Word, refine).alignment());
        assert_eq!(
            regions,
            [Region { kind: Kind::WordMerged, bases: vec![0..1], sides: vec![0..1, 0..1] }],
            "refine {refine}"
        );
        assert_eq!(
            word_merge(&inputs, &regions[0], SameChange::Accept).as_deref(),
            Some("let y = 2;\n")
        );
    }
}
